"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["2550"],{93072(o){o.exports=JSON.parse('{"registro":{"codigo":"uniplus.selecao.dados_edital.periodo_inscricao_invalido","status":422,"titulo":"O fim do per\xedodo de inscri\xe7\xe3o n\xe3o pode anteceder o in\xedcio"},"descricao":{"codigo":"uniplus.selecao.dados_edital.periodo_inscricao_invalido","requisitos":[],"oQueAconteceu":["O per\xedodo de inscri\xe7\xe3o do edital tem o fim anterior ao in\xedcio. Um per\xedodo com fim\\nigual ao in\xedcio \xe9 aceito; s\xf3 o fim anterior \xe9 recusado. A recusa sai com **422**,\\nsem indicar campo.","H\xe1 duas fontes para o per\xedodo, e s\xf3 uma delas permite este erro na publica\xe7\xe3o.\\nQuando o processo tem fase do cronograma que coleta inscri\xe7\xe3o, o per\xedodo \xe9\\nprojetado do per\xedodo dessa fase e n\xe3o pode ser informado no pedido; como o per\xedodo\\nda fase j\xe1 \xe9 recusada quando termina antes de come\xe7ar\\n([`janela_invertida`](/erros/uniplus.selecao.fase_cronograma.janela_invertida)), a\\ninvers\xe3o n\xe3o chega at\xe9 aqui por esse caminho. Quando o processo n\xe3o tem fase que\\ncolete inscri\xe7\xe3o, como o de resultado importado, o in\xedcio e o fim s\xe3o informados\\nno pedido de publica\xe7\xe3o (`PeriodoInscricaoInicio` e `PeriodoInscricaoFim`), e \xe9\\nesse par que pode vir invertido. A confer\xeancia vem depois da dos anexos do edital\\ne antes da confer\xeancia de conformidade da configura\xe7\xe3o. Um extremo ausente ou\\nzerado \xe9 recusado antes, com outro c\xf3digo\\n([`periodo_inscricao_obrigatorio`](/erros/uniplus.selecao.dados_edital.periodo_inscricao_obrigatorio)).","O mesmo valor \xe9 conferido quando uma vers\xe3o congelada \xe9 lida de volta, na\\nretifica\xe7\xe3o em ato \xfanico."],"comoResolver":["Corrija o in\xedcio e o fim do per\xedodo no pedido de publica\xe7\xe3o ou na retifica\xe7\xe3o em\\nato \xfanico (confira o dia e o fuso) e repita a opera\xe7\xe3o. Se o erro vem da leitura\\nde uma vers\xe3o j\xe1 publicada, o per\xedodo vem da vers\xe3o congelada, e reenviar a\\nconfigura\xe7\xe3o n\xe3o o corrige: a causa deve ser investigada pela equipe t\xe9cnica do\\nUni+, porque nenhum caminho de publica\xe7\xe3o grava um per\xedodo invertido."],"ondeAparece":["Publica\xe7\xe3o inicial do processo seletivo","Retifica\xe7\xe3o em ato \xfanico"]},"modulo":{"id":"selecao","nome":"Sele\xe7\xe3o","assunto":"Dados edital"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"2b5f8240ef92ed3147f41ca40a325e729f45c7bd"}}')}}]);